import {resolveAbilitySet} from './ability-set-resolution.js';

export function renderAbilitySetComposition(body,doc,files,hooks,edit){
 const d=body.ownerDocument,make=(tag,text)=>{const e=d.createElement(tag);if(text!==undefined)e.textContent=text;return e;},view=doc.view??={};
 const title=path=>files.find(f=>f.path===path)?.name||path.split('/').at(-1),choices=files.filter(f=>f.kind==='abilityset'&&f.path!==doc.path),section=make('section'),parentLabel=make('label','부모 세트'),parent=make('select');parent.dataset.abilitySetParent='';parent.setAttribute('aria-label','부모 세트');
 for(const row of [{path:'',name:'없음'},...choices,...(doc.data.parent&&!choices.some(f=>f.path===doc.data.parent)?[{path:doc.data.parent,name:doc.data.parent}]:[])]){const option=make('option',row.name);option.value=row.path;parent.append(option);}parent.value=doc.data.parent||'';parent.onchange=()=>edit(data=>data.parent=parent.value);parentLabel.append(parent);section.append(parentLabel);
 const includes=doc.data.includes||[],bar=make('div'),select=make('select'),add=make('button','세트 추가');bar.className='form-section-heading';select.dataset.abilitySetInclude='';select.setAttribute('aria-label','합성할 세트');for(const row of choices.filter(f=>f.path!==doc.data.parent&&!includes.includes(f.path))){const option=make('option',row.name);option.value=row.path;select.append(option);}add.dataset.abilitySetIncludeAdd='';add.disabled=!select.options.length;add.onclick=()=>edit(data=>(data.includes??=[]).push(select.value));bar.append(make('h3','합성 세트 · '+includes.length),select,add);section.append(bar);
 let offset=Math.max(0,Math.min(view.abilitySetIncludeOffset||0,Math.max(0,includes.length-1)));offset=Math.floor(offset/25)*25;for(let index=offset;index<Math.min(includes.length,offset+25);index++){const path=includes[index],row=make('div'),name=make('button',title(path)),up=make('button','위'),down=make('button','아래'),remove=make('button','삭제');row.className='ability-set-reference';name.title=path;name.onclick=()=>hooks.openAsset?.(path);up.disabled=index===0;down.disabled=index===includes.length-1;up.setAttribute('aria-label',title(path)+' 위로');down.setAttribute('aria-label',title(path)+' 아래로');up.onclick=()=>edit(data=>{[data.includes[index-1],data.includes[index]]=[data.includes[index],data.includes[index-1]];});down.onclick=()=>edit(data=>{[data.includes[index+1],data.includes[index]]=[data.includes[index],data.includes[index+1]];});remove.onclick=()=>edit(data=>data.includes.splice(index,1));row.append(name,up,down,remove);section.append(row);}
 if(includes.length>25){const pages=make('div'),previous=make('button','이전'),next=make('button','다음');pages.className='form-section-heading';previous.disabled=offset===0;next.disabled=offset+25>=includes.length;for(const [button,delta]of[[previous,-25],[next,25]])button.onclick=()=>{view.abilitySetIncludeOffset=offset+delta;hooks.renderComposition?.();};pages.append(previous,make('output',(offset+1)+'–'+Math.min(includes.length,offset+25)+' / '+includes.length),next);section.append(pages);}
 body.append(section);const preview=make('section'),toggle=make('button','합성 결과'),panel=make('div'),status=make('output'),controls=make('div'),mode=make('select'),search=make('input'),refresh=make('button','갱신'),table=make('table'),previous=make('button','이전'),next=make('button','다음'),page=make('output');preview.className='ability-set-resolved';table.className='ability-set-resolved-table';toggle.dataset.abilitySetResolved='';search.type='search';search.placeholder='결과 검색';search.setAttribute('aria-label','합성 결과 검색');mode.setAttribute('aria-label','합성 결과 종류');for(const [value,label]of[['attributes','속성'],['abilities','능력'],['tags','태그'],['sources','세트']]){const option=make('option',label);option.value=value;mode.append(option);}const state=view.abilitySetResolvedView??={section:'attributes',search:'',offset:0};mode.value=state.section;search.value=state.search;controls.className='form-section-heading';controls.append(mode,search,refresh);const pages=make('div');pages.className='form-section-heading';pages.append(previous,page,next);panel.append(status,controls,table,pages);preview.append(toggle,panel);body.append(preview);let result,generation=0;
 const open=()=>view.abilitySetPreviewOpen&&panel.isConnected;
 function draw(){if(!result)return;const data=result.data,source=result.provenance,query=search.value.toLocaleLowerCase(),rows=(mode.value==='attributes'?data.attributes.map(row=>({...row,source:source.attributes[row.name]})):mode.value==='abilities'?data.abilities.map(asset=>({asset,source:source.abilities[asset]})):mode.value==='tags'?data.grantedTags.map(tag=>({tag,source:source.tags[tag]})):result.sources.map(row=>({asset:row.path,name:row.name}))).filter(row=>Object.values(row).some(v=>String(v).toLocaleLowerCase().includes(query)));state.offset=Math.max(0,Math.min(state.offset,Math.max(0,rows.length-1)));state.offset=Math.floor(state.offset/25)*25;table.replaceChildren();const head=make('thead'),tr=make('tr'),columns=mode.value==='attributes'?['이름','기본값','최소','최대','출처','']:mode.value==='sources'?['세트','이름']:['이름','출처'];for(const label of columns){const th=make('th',label);tr.append(th);}head.append(tr);const tbody=make('tbody');table.append(head,tbody);
  for(const row of rows.slice(state.offset,state.offset+25)){const tr=make('tr');if(mode.value==='attributes'){for(const value of[row.name,row.base,row.min,row.max])tr.append(make('td',value));const origin=make('td',title(row.source));origin.title=row.source;tr.append(origin);const cell=make('td');if(!doc.data.attributes.some(a=>a.name===row.name)){const override=make('button','재정의');override.dataset.abilitySetOverride=row.name;override.onclick=()=>edit(data=>data.attributes.push({name:row.name,base:row.base,min:row.min,max:row.max,...(row.calculation?{calculation:structuredClone(row.calculation)}:{})}));cell.append(override);}tr.append(cell);}else{for(const value of mode.value==='sources'?[row.asset,row.name]:[row.asset||row.tag,row.source]){const cell=make('td',String(value));cell.title=String(value);tr.append(cell);}}tbody.append(tr);}previous.disabled=state.offset===0;next.disabled=state.offset+25>=rows.length;page.textContent=(rows.length?state.offset+1:0)+'–'+Math.min(rows.length,state.offset+25)+' / '+rows.length;
 }
 async function load(){const token=++generation,root=structuredClone(doc.data),stamp=JSON.stringify(root),observed=new Map();refresh.disabled=true;status.textContent='불러오는 중';try{const resolved=await resolveAbilitySet(doc.path,async path=>{if(!open())throw Error('취소');const data=path===doc.path?root:await hooks.readAsset(path);observed.set(path,JSON.stringify(data));return data;});for(const [path,before]of observed){if(!open()||token!==generation)return;if(path!==doc.path&&JSON.stringify(await hooks.readAsset(path))!==before)throw Error('참조 세트가 변경됐어요. 갱신하세요.');}if(!open()||token!==generation)return;if(JSON.stringify(doc.data)!==stamp)throw Error('문서가 변경됐어요. 갱신하세요.');result=resolved;status.textContent='속성 '+result.data.attributes.length+' · 능력 '+result.data.abilities.length+' · 태그 '+result.data.grantedTags.length+' · 세트 '+result.sources.length;draw();}catch(error){if(open()&&token===generation)status.textContent=error.message;}finally{if(token===generation)refresh.disabled=false;}}
 const visibility=()=>{panel.hidden=!view.abilitySetPreviewOpen;toggle.setAttribute('aria-expanded',String(!!view.abilitySetPreviewOpen));};toggle.onclick=()=>{view.abilitySetPreviewOpen=!view.abilitySetPreviewOpen;generation++;visibility();if(view.abilitySetPreviewOpen)load();};refresh.onclick=load;mode.onchange=()=>{state.section=mode.value;state.offset=0;draw();};search.oninput=()=>{state.search=search.value;state.offset=0;draw();};previous.onclick=()=>{state.offset-=25;draw();};next.onclick=()=>{state.offset+=25;draw();};visibility();if(view.abilitySetPreviewOpen)load();
}
